const IMG_ASSAD='data:image/png;base64,';
const IMG_US='data:image/png;base64,';
const IMG_REFUGEE='data:image/png;base64,';
const IMG_CERMA='data:image/png;base64,';
const questions=[
{q:'Qual é o foco da habilidade H8 do Enem trabalhada na aula?',o:['Analisar a ação dos Estados nos fluxos populacionais e em problemas econômico-sociais.','Decorar capitais e fronteiras sem interpretar contextos.','Calcular o crescimento do PIB dos países asiáticos.','Reconhecer apenas elementos naturais em mapas.'],a:0,e:'A H8 pede analisar como os Estados atuam diante dos movimentos populacionais e dos problemas econômico-sociais.'},
{q:'Em que contexto histórico começou a Guerra Civil Síria?',o:['Como parte da Primavera Árabe, em 2011.','Durante a Guerra Fria, em 1962.','Após a criação da ONU, em 1945.','Durante a Primavera de Praga, em 1968.'],a:0,e:'O conflito começou em março de 2011, como parte da onda de protestos da Primavera Árabe.'},
{q:'Em qual cidade síria ocorreram os protestos iniciais de 2011?',o:['Aleppo.','Damasco.','Deraa.','Homs.'],a:2,e:'Os protestos populares começaram em Deraa, em reação à repressão e às condições políticas e sociais.'},
{q:'Qual acontecimento intensificou os protestos contra o governo sírio?',o:['A assinatura de um acordo de paz regional.','A repressão violenta a estudantes que fizeram pichações contra Assad.','A descoberta de petróleo no litoral sírio.','A realização de eleições plenamente democráticas.'],a:1,e:'A repressão a estudantes que picharam mensagens contra Assad foi um estopim importante dos protestos.'},
{q:'Quais eram algumas reivindicações dos manifestantes no início do conflito?',o:['Menos corrupção, mais democracia e melhor qualidade de vida.','Expansão territorial e criação de uma nova moeda.','Fim da educação pública e aumento de impostos.','Controle estrangeiro direto sobre todas as cidades.'],a:0,e:'Os protestos demandavam menos corrupção, mais democracia e melhores condições de vida.',img:IMG_ASSAD},
{q:'Quem governou a Síria de 2000 a 2024, segundo a aula?',o:['Ahmed al-Sharaa.','Hafez al-Assad.','Bashar al-Assad.','Recep Tayyip Erdoğan.'],a:2,e:'Bashar al-Assad sucedeu seu pai, Hafez al-Assad, e governou a Síria de 2000 a 2024.'},
{q:'A Guerra na Síria começou apenas por disputas religiosas?',o:['Sim. A religião foi a única causa desde o primeiro dia.','Não. Houve uma combinação de repressão política, desigualdade, influência externa, radicalização e disputa pelo poder.','Sim. O conflito foi causado exclusivamente por diferenças entre sunitas e xiitas.','Não. A guerra começou apenas por um terremoto.'],a:1,e:'A aula destaca causas múltiplas: repressão política, desigualdade social, influências internacionais, radicalização e disputas de poder.'},
{q:'Qual relação religiosa é apresentada na aula ao explicar parte das divisões do conflito?',o:['Assad representava a minoria xiita e grupos opositores se associaram a movimentos sunitas fundamentalistas.','Assad era budista e os rebeldes eram hindus.','Todos os grupos envolvidos pertenciam à mesma corrente religiosa.','Os grupos religiosos não tiveram qualquer relação com o conflito.'],a:0,e:'A aula aborda a presença de um governo associado à minoria xiita e de grupos opositores sunitas fundamentalistas, sem reduzir o conflito somente à religião.'},
{q:'Qual grupo é citado como um dos atores fundamentalistas envolvidos na guerra?',o:['Estado Islâmico (ISIS).','Mercosul.','União Europeia.','OTAN como partido sírio.'],a:0,e:'O Estado Islâmico (ISIS) é citado, assim como o Hayat Tahrir al-Sham (HTS).'},
{q:'Qual conjunto reúne atores envolvidos no conflito sírio?',o:['Governo sírio, rebeldes, Estado Islâmico, curdos e potências estrangeiras.','Somente o governo sírio e organizações humanitárias.','Apenas países europeus sem grupos internos.','Somente os curdos e a ONU.'],a:0,e:'A guerra envolveu governo, rebeldes, ISIS, curdos e intervenções de países como EUA, Rússia, Irã e Turquia.'},
{q:'Qual evento militar foi apontado como decisivo em 2015?',o:['A intervenção militar da Rússia.','A retirada de todos os grupos armados.','A criação do CERMA/PR.','A queda imediata de Assad.'],a:0,e:'A intervenção russa em 2015 reduziu a força dos adversários de Assad e ampliou a influência russa no Oriente Médio.',img:IMG_US},
{q:'Qual foi um efeito da intervenção russa de 2015?',o:['Enfraqueceu os adversários de Assad e ajudou a garantir a sobrevivência de seu regime.','Eliminou todos os grupos rebeldes em poucos dias.','Encerrou a crise de refugiados no Líbano.','Transformou a Síria em uma democracia estável imediatamente.'],a:0,e:'A campanha de bombardeios russos diminuiu a força de adversários e garantiu a continuidade do regime de Assad naquele período.'},
{q:'Em que data Bashar al-Assad foi deposto, conforme a linha do tempo apresentada?',o:['8 de dezembro de 2024.','11 de setembro de 2001.','1º de janeiro de 2011.','15 de março de 2025.'],a:0,e:'A apresentação registra a deposição de Bashar al-Assad em 8/12/2024.'},
{q:'Quem foi nomeado presidente interino da Síria em janeiro de 2025, segundo a aula?',o:['Ahmed al-Sharaa.','Mohamed Morsi.','Hafez al-Assad.','Muammar al-Gaddafi.'],a:0,e:'Ahmed al-Sharaa foi nomeado presidente interino em janeiro de 2025, com promessa de reestruturar instituições públicas.'},
{q:'O que a declaração constitucional de março de 2025 previa, de acordo com o conteúdo?',o:['Papel central da lei islâmica, direitos das mulheres e liberdade de expressão.','Fim de qualquer instituição pública e das eleições.','Retorno automático ao governo de Bashar al-Assad.','Divisão da Síria em colônias estrangeiras.'],a:0,e:'A declaração manteve papel central para a lei islâmica e previu direitos das mulheres e liberdade de expressão.'},
{q:'Por que a guerra síria é descrita como um conflito multifacetado?',o:['Porque diferentes atores internos e externos tinham interesses e agendas próprias.','Porque aconteceu em apenas uma cidade.','Porque não envolveu potências internacionais.','Porque não houve grupos armados.'],a:0,e:'A multiplicidade de atores e interesses — internos e externos — dificultou a resolução e prolongou o sofrimento da população.'},
{q:'Quais países são citados como apoiadores do governo de Assad?',o:['Rússia e Irã.','EUA e Turquia apenas.','Alemanha e França.','Líbano e Canadá.'],a:0,e:'O material afirma que Rússia e Irã apoiaram Assad.'},
{q:'Qual foi a posição dos Estados Unidos descrita no material?',o:['Apoiaram rebeldes moderados e atacaram o Estado Islâmico.','Apoiaram exclusivamente o governo de Assad.','Não tiveram qualquer atuação no conflito.','Apoiaram somente as forças curdas contra todos os demais grupos.'],a:0,e:'A apresentação aponta apoio dos EUA a rebeldes moderados e ataques ao Estado Islâmico.'},
{q:'Qual país combateu forças curdas e também aparece como ator externo do conflito?',o:['Turquia.','Japão.','Argentina.','Índia.'],a:0,e:'A Turquia combateu forças curdas e participou do complexo xadrez geopolítico da guerra.'},
{q:'Como a crise humanitária síria foi agravada em 2023?',o:['Pelos terremotos que atingiram a Síria e a Turquia.','Por uma queda global no preço do petróleo.','Por uma epidemia ocorrida somente na Europa.','Por uma eleição municipal.'],a:0,e:'Os terremotos de 2023 agravaram uma crise humanitária que já existia desde o início do conflito.',img:IMG_REFUGEE},
{q:'Qual foi uma consequência econômica citada na aula?',o:['Redução de cerca de 50% do PIB no início do conflito.','Crescimento de 50% do PIB durante a guerra.','Fim da inflação e valorização da moeda.','Expansão imediata dos setores agrícola e petrolífero.'],a:0,e:'A economia síria sofreu redução de cerca de 50% do PIB, associada à escassez, inflação, sanções e colapso produtivo.'},
{q:'Quanto tempo a reestruturação econômica e social da Síria poderia levar, segundo as previsões apresentadas?',o:['Em torno de 20 anos após o fim do conflito.','Apenas seis meses.','Exatamente 100 anos.','Duas semanas.'],a:0,e:'A previsão apresentada fala em cerca de 20 anos, período ainda ampliado pela pandemia e pelos terremotos.'},
{q:'Qual consequência social e geopolítica ganhou destaque na guerra?',o:['Crise de refugiados sírios e tensões entre potências como EUA e Rússia.','Fim dos deslocamentos populacionais e cooperação total entre as potências.','Apenas aumento do turismo na região.','Redução das migrações e fim da xenofobia.'],a:0,e:'A guerra produziu uma crise de refugiados e afetou as relações entre potências que apoiavam diferentes lados.'},
{q:'Por que os refugiados sírios enfrentaram dificuldades em países europeus?',o:['Muitos países não possuíam infraestrutura de acolhimento para todos, e ocorreram manifestações xenofóbicas.','Porque todos os países europeus fecharam suas escolas.','Porque os refugiados eram combatentes em todos os casos.','Porque não havia qualquer deslocamento para a Europa.'],a:0,e:'O material destaca falta de infraestrutura de acolhimento, manifestações xenofóbicas e violência contra refugiados.'},
{q:'Na questão do Enem 2018, onde ocorre a cena descrita sobre refugiados sírios?',o:['Beirute, no Líbano.','Deraa, na Síria.','Moscou, na Rússia.','Ancara, na Turquia.'],a:0,e:'O texto ocorre em Beirute, no Líbano, mostrando que os efeitos da guerra ultrapassam as fronteiras sírias.'},
{q:'O deslocamento de civis sírios que fogem da guerra pode ser compreendido como:',o:['Migração forçada e busca de proteção em outro país.','Turismo internacional voluntário.','Migração exclusivamente por lazer.','Expansão territorial planejada pelo governo sírio.'],a:0,e:'Refugiados fogem de guerras, conflitos armados ou perseguições e buscam proteção em outro território.'},
{q:'Qual conceito descreve o abandono forçado do território em consequência de conflitos?',o:['Desterritorialização forçada.','Hibridização cultural.','Urbanização planejada.','Transumância.'],a:0,e:'A situação dos refugiados sírios no Líbano é analisada como desterritorialização forçada decorrente de conflitos armados.'},
{q:'O que significa dizer que uma pessoa é refugiada?',o:['É alguém que foge de guerra, conflito armado ou perseguição e busca proteção.','É alguém que viaja apenas para estudar.','É alguém que muda de cidade por preferência turística.','É alguém que pertence obrigatoriamente a um grupo armado.'],a:0,e:'A definição trabalhada diferencia refugiados civis de combatentes e de pessoas que migram apenas por turismo ou lazer.'},
{q:'Qual é a função do CERMA/PR, criado em 2015?',o:['Auxiliar na implementação e fiscalização de políticas públicas para proteger direitos de refugiados, migrantes e apátridas.','Comandar operações militares na Síria.','Controlar a produção de petróleo sírio.','Organizar eleições em todos os países do Oriente Médio.'],a:0,e:'O CERMA/PR atua na promoção e proteção dos direitos de refugiados, migrantes e apátridas no Paraná.',img:IMG_CERMA},
{q:'O descritor d09, citado no final da aula, relaciona-se a qual capacidade?',o:['Reconhecer diferentes contextos geopolíticos e suas implicações.','Identificar apenas tipos de clima.','Resolver equações econômicas sem contexto.','Memorizar nomes de rios e montanhas.'],a:0,e:'O d09 envolve compreender contextos geopolíticos dinâmicos e seus efeitos nas relações entre países, blocos e populações.'}
];
let student='',current=0,score=0,answered=false;
const $=id=>document.getElementById(id);
function initImages(){ $('heroImage').src=IMG_ASSAD; }
function start(ev){ev.preventDefault();const n=$('studentName').value.trim();if(!n){$('studentName').focus();return}student=n;current=0;score=0;$('home').style.display='none';$('result').style.display='none';$('quiz').style.display='block';$('studentDisplay').textContent=student;render();}
function render(){answered=false;$('feedback').className='feedback';$('feedback').textContent='';$('next').hidden=true;const item=questions[current];$('counter').textContent=`Questão ${current+1} de ${questions.length}`;$('points').textContent=`${score} acerto${score===1?'':'s'}`;$('bar').style.width=`${current/questions.length*100}%`;$('question').textContent=item.q;const im=$('questionImage');if(item.img){im.src=item.img;im.style.display='block'}else{im.removeAttribute('src');im.style.display='none'}$('options').innerHTML=item.o.map((x,i)=>`<button class="option" type="button" data-i="${i}"><span class="letter">${String.fromCharCode(65+i)}</span><span>${x}</span></button>`).join('');document.querySelectorAll('.option').forEach(b=>b.addEventListener('click',()=>answer(+b.dataset.i)));}
function answer(index){if(answered)return;answered=true;const item=questions[current],bs=document.querySelectorAll('.option');bs.forEach((b,i)=>{b.disabled=true;if(i===item.a)b.classList.add('correct');if(i===index&&i!==item.a)b.classList.add('wrong')});const f=$('feedback');if(index===item.a){score++;f.className='feedback show good';f.innerHTML=`<strong>Correto!</strong> ${item.e}`}else{f.className='feedback show bad';f.innerHTML=`<strong>${index===-1?'Tempo esgotado.':'Atenção!'}</strong> A resposta correta é <strong>${String.fromCharCode(65+item.a)}</strong>. ${item.e}`}$('points').textContent=`${score} acerto${score===1?'':'s'}`;$('bar').style.width=`${(current+1)/questions.length*100}%`;$('next').textContent=current===questions.length-1?'Ver resultado →':'Próxima →';$('next').hidden=false;$('next').focus();}
function next(){if(!answered)return;if(current===questions.length-1)finish();else{current++;render()}}
function finish(){$('quiz').style.display='none';$('result').style.display='block';$('resultName').textContent=student;$('finalScore').textContent=score;const r=score/questions.length;$('message').textContent=r>=.85?'Excelente! Você dominou as relações entre conflito, território, atores internacionais e fluxos populacionais.':r>=.6?'Bom trabalho! Você compreendeu os pontos principais. Revise os feedbacks para consolidar o conteúdo.':'Você já começou a construir seu repertório. Reveja a aula, principalmente causas, atores e consequências humanitárias, e tente novamente.'}
function again(){current=0;score=0;$('result').style.display='none';$('quiz').style.display='block';render()}
function newStudent(){$('result').style.display='none';$('home').style.display='grid';$('studentName').value='';$('studentName').focus()}
$('startForm').addEventListener('submit',start);$('next').addEventListener('click',next);$('again').addEventListener('click',again);$('newStudent').addEventListener('click',newStudent);initImages();
